            return False
        i += 6
    return True

def primes_below(n: int) -> list[int]:
    if n <= 2:
        return []
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    i = 2
    while i * i < n:
        if sieve[i]:
            for j in range(i * i, n, i):
                sieve[j] = False
        i += 1
    return [k for k, is_prime in enumerate(sieve) if is_prime]

