from concurrent.futures import ThreadPoolExecutor


def squares(n: int) -> int:
    if n <= 0:
        return 0

    mid = n // 2

    def sum_squares(lo: int, hi: int) -> int:
        return sum(i * i for i in range(lo, hi + 1))

    with ThreadPoolExecutor(max_workers=2) as pool:
        first = pool.submit(sum_squares, 1, mid)
        second = pool.submit(sum_squares, mid + 1, n)
        return first.result() + second.result()

def total_qty(text: str) -> int:
    # Decode the JSON text; any parse failure means "doesn't decode".
    try:
        data = json.loads(text)
    except (ValueError, TypeError, RecursionError):
        return -1

    # The decoded value must be a list of Item-shaped objects.
    if not isinstance(data, list):
        return -1

    items = []
    for entry in data:
        if not isinstance(entry, dict):
            return -1
        name = entry.get("name")
        qty = entry.get("qty")
        if not isinstance(name, str):
            return -1
        # bool is a subclass of int in Python, so reject it explicitly.
        if isinstance(qty, bool) or not isinstance(qty, int):
            return -1
        items.append(Item(name=name, qty=qty))

    return sum(item.qty for item in items)

