import io


def csv(n: int) -> str:
    # Append to an in-memory text buffer rather than using `str +=`,
    # so the loop is guaranteed linear time instead of potentially quadratic.
    text = io.StringIO()
    for i in range(1, n + 1):
        if i > 1:
            text.write(",")
        text.write(str(i))
    return text.getvalue()

def strip_vowels(text: str) -> str:
    vowels = set("aeiouAEIOU")
    return "".join(ch for ch in text if ch not in vowels)

def binary(n: int) -> str:
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(str(n & 1))
        n >>= 1
    return "".join(reversed(digits))

from collections import Counter


def mode(xs: list[int]) -> int:
    if not xs:
        raise ValueError("mode() requires a non-empty list")
    counts = Counter(xs)
    best = max(counts.values())
    return min(x for x, c in counts.items() if c == best)

def zip_map(keys: list[str], values: list[int]) -> dict[str, int]:
    # zip stops at the shorter list; a repeated key keeps its last value.
    return dict(zip(keys, values))

def triangle(a: int, b: int, c: int) -> str:
    if a <= 0 or b <= 0 or c <= 0:
        return "invalid"
    if a >= b + c or b >= a + c or c >= a + b:
        return "invalid"
    if a == b == c:
        return "equilateral"
    if a == b or b == c or a == c:
        return "isosceles"
    return "scalene"

def collatz(n: int) -> int:
    if n < 1:
        raise ValueError("n must be a positive integer")
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

def top(players: list[Player], k: int) -> list[str]:
    if k <= 0:
        return []
    ranked = sorted(players, key=lambda p: p.score, reverse=True)
    return [p.name for p in ranked[:k]]

def hex(r: int, g: int, b: int) -> str:
    for name, value in (("r", r), ("g", g), ("b", b)):
        if not 0 <= value <= 255:
            raise ValueError(f"{name} must be in range 0..255, got {value}")
    return f"#{r:02x}{g:02x}{b:02x}"

