def fib(n: int) -> int:
    """Return the nth Fibonacci number, with fib(0) = 0 and fib(1) = 1."""
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    # Fast doubling: process bits of n from most significant to least.
    # Invariant: (a, b) == (F(k), F(k+1)) for the prefix k of n processed so far.
    a, b = 0, 1
    for bit in bin(n)[2:]:
        c = a * (2 * b - a)   # F(2k)
        d = a * a + b * b     # F(2k+1)
        if bit == '1':
            a, b = d, c + d   # (F(2k+1), F(2k+2))
        else:
            a, b = c, d       # (F(2k), F(2k+1))
    return a

